CREATE TABLE IF NOT EXISTS finance_allocation_lines ( id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, allocation_set_id BIGINT UNSIGNED NOT NULL, download_id BIGINT UNSIGNED NOT NULL, kind VARCHAR(8) NOT NULL, source_id BIGINT UNSIGNED NOT NULL, cents BIGINT UNSIGNED NOT NULL, uacs_code VARCHAR(20) NULL, tax_disposition VARCHAR(32) NULL, evidence_reference VARCHAR(255) NOT NULL, PRIMARY KEY (id), UNIQUE KEY uq_fal_source (allocation_set_id, download_id, kind, source_id), KEY ix_fal_download (download_id), CONSTRAINT fk_fal_set FOREIGN KEY (allocation_set_id) REFERENCES finance_allocation_sets(id), CONSTRAINT fk_fal_download FOREIGN KEY (download_id) REFERENCES fund_events(id) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
